// v9.75: draft entry, exact hit type, per-run RBI, display-only counts and atomic Undo.
function draft(f,item={kind:'infield-hit',label:'内野安打',result:'単打'}){f.state.selectedPosition='投手';f.c.openScoreEntry(item,'投手');return vm.runInContext('scoreEntry',f.c);}
function plan(f,d){return f.c.analyzeScoreEntry(d);}
function commit(f){f.c.commitScoreEntry();f.flush();}
function errorHome(f){f.runner('first','p2');const d=draft(f);d.primary.first='third';d.extras=[{key:'first',to:'home',reason:'悪送球'},{key:'batter',to:'home',reason:'悪送球'}];return d;}
check('U01','新入力：内野安打後に悪送球で2人生還は単打・2得点0打点',{score:2,h:1,hr:0,rbi:0,runs:1,runnerRuns:1,outs:0},()=>{const f=fixture();errorHome(f);commit(f);return {score:f.ls.teamScore,h:stat(f).batting.h,hr:stat(f).batting.hr,rbi:stat(f).batting.rbi,runs:stat(f).batting.runs,runnerRuns:stat(f,'p2').batting.runs,outs:f.state.outs};});
check('U02','確認画面まで進んでも得点・アウト・ログ・打順は未確定',{runs:2,score:0,out:0,logs:0,batter:'p1',messages:0},()=>{const f=fixture(),d=errorHome(f);d.stage=3;f.c.renderScoreEntry();const p=plan(f,d);f.flush();return {runs:p.runs,score:f.state.score,out:f.state.outs,logs:f.ls.logs.length,batter:f.ls.batterId,messages:f.messages.length};});
check('U03','下書き取消で得点・走者・打順・Undo履歴を変更しない',{score:0,first:'p2',batter:'p1',logs:0,history:0},()=>{const f=fixture();errorHome(f);f.c.cancelScoreEntry();f.flush();return {score:f.state.score,first:f.state.bases.first.id,batter:f.ls.batterId,logs:f.ls.logs.length,history:f.c.api.history.length};});
check('U04','新入力の取り消しで2得点と両走者を一括復元',{score:0,first:'p2',logs:0,batter:'p1'},()=>{const f=fixture();errorHome(f);commit(f);f.document.getElementById('undoBtn').click();f.flush();return {score:f.ls.teamScore,first:f.state.bases.first.id,logs:f.ls.logs.length,batter:f.ls.batterId};});
check('U05','明示した本塁打は打者本人を含む2打点',{h:1,hr:1,rbi:2,score:2},()=>{const f=fixture();f.runner('first','p2');draft(f,{kind:'hit',label:'本塁打',result:'本塁打'});commit(f);return {h:stat(f).batting.h,hr:stat(f).batting.hr,rbi:stat(f).batting.rbi,score:f.ls.teamScore};});
check('U06','単打で走者生還＋打者は悪送球で生還なら1打点',{score:2,rbi:1,hr:0},()=>{const f=fixture();f.runner('first');const d=draft(f);d.primary.first='home';d.extras=[{key:'batter',to:'home',reason:'悪送球'}];commit(f);return {score:f.ls.teamScore,rbi:stat(f).batting.rbi,hr:stat(f).batting.hr};});
check('U07','記録員の打点訂正は対象走者だけに保存する',{rbi:1,manual:true,credited:['first']},()=>{const f=fixture(),d=errorHome(f);d.rbiOverrides.first=true;commit(f);const p=f.ls.logs.at(-1);return {rbi:p.rbi,manual:p.rbiDecisions.find(x=>x.key==='first').manual,credited:p.rbiDecisions.filter(x=>x.credited).map(x=>x.key)};});
check('U08','本塁打以外で打者自身の生還を打点に加算させない',0,()=>{const f=fixture(),d=errorHome(f);d.rbiOverrides.batter=true;return plan(f,d).rbi;});
check('U09','追加進塁で二塁へ達しても単打のまま',{h:1,doubles:0,second:'p1',result:'単打'},()=>{const f=fixture(),d=draft(f);d.extras=[{key:'batter',to:'second',reason:'返球の間'}];commit(f);return {h:stat(f).batting.h,doubles:stat(f).batting.doubles,second:f.state.bases.second.id,result:f.ls.logs.at(-1).result};});
