// v9.76: the actual order-review controls, message bridge and substitution transaction.
function orderFixture(options={}){
 const f=fixture(options);bench(f);
 const positions={p1:'捕',p2:'一',p3:'二',p4:'三',p5:'遊',p6:'左',p7:'中',p8:'右',p9:'投'};
 f.c.api.siteBridge.fieldingPositions={...positions};f.ls.fieldingPositions={...positions};
 f.orderTimers=[];f.p.clearTimeout=()=>{};f.p.setTimeout=(fn,delay=0)=>{if(delay>=1000)f.orderTimers.push(fn);else f.tasks.push(fn);return f.orderTimers.length;};
 Object.assign(f.p,{orderModal:f.p.document.getElementById('live-order-modal'),orderError:f.p.document.getElementById('live-order-error'),orderSlots:f.p.document.getElementById('live-order-slots'),orderMembers:f.p.document.getElementById('live-order-members'),orderDraft:f.ls.battingOrder.slice(),orderPositionDraft:{...positions},orderSelectedMember:'',orderDragMember:'',orderDuplicatePositions:new Set(),orderFieldSlot:null,FIELD_POSITION_NAMES:{投:'投手',捕:'捕手',一:'一塁',二:'二塁',三:'三塁',遊:'遊撃',左:'左翼',中:'中堅',右:'右翼'},closeOrderField(){},renderOrderEditor(){},clearTimeout(){}});
 const names=['orderEditorDefensiveExtras','orderEditorChanges','orderEditorFingerprint','memberLabelById','showOrderError','clearOrderError','syncPitcherFromOrder','openOrderModal','closeOrderModal','confirmOrder'];
 const a=html.indexOf('    let orderChangeReview=null'),b=html.indexOf('    function openOrderModal(',a);assert.ok(a>=0&&b>a);
 vm.runInContext(names.map(extract).join('\n')+'\n'+html.slice(a,b),f.p);
 f.c.api.render();f.flush();
 return f;
}
function editOrder(f,replacements={},positions={}){
 f.p.openOrderModal(false);for(const [slot,id]of Object.entries(replacements))f.p.orderDraft[Number(slot)]=id;Object.assign(f.p.orderPositionDraft,positions);f.p.confirmOrder();
 return vm.runInContext('orderChangeReview',f.p);
}
function orderKinds(f,kinds){const review=vm.runInContext('orderChangeReview',f.p);for(const [key,kind]of Object.entries(kinds))review.controls[key].value=kind;}
function commitOrder(f){f.p.confirmOrder();f.flush();}
check('O01','オーダー変更を確認しても区分確定前にはログ・打者を変更しない',{logs:0,batter:'p1',order:'p1',review:true},()=>{const f=orderFixture();editOrder(f,{0:'p10'},{p10:'捕'});f.flush();return {logs:f.ls.logs.length,batter:f.ls.batterId,order:f.ls.battingOrder[0],review:!f.p.document.getElementById('live-order-review').hidden};});
